import pytest
from pagedserve.attn.paged_triton import _tile_for

def test_tile_divides_block_size_for_all_supported_blocks():
    for bs in (16, 32, 64, 128, 256):
        for groups_pad in (1, 2, 4, 8, 16):
            for d in (16, 64, 128):
                t = _tile_for(bs, d, groups_pad)
                assert bs % t == 0

